const updateRoutingRule = `-- name: UpdateRoutingRule :one
UPDATE routing_rules
SET name = $1, position = $2, is_active = $3,
    conditions = $4, team_id = $5, skills = $6
WHERE organization_id = $7 AND id = $8
RETURNING id, uuid, organization_id, name, position, is_active, conditions, team_id, skills, created_at, updated_at
`

type UpdateRoutingRuleParams struct {
	Name           string      `json:"name"`
	Position       int32       `json:"position"`
	IsActive       bool        `json:"is_active"`
	Conditions     []byte      `json:"conditions"`
	TeamID         pgtype.Int8 `json:"team_id"`
	Skills         []string    `json:"skills"`
	OrganizationID int64       `json:"organization_id"`
	ID             int64       `json:"id"`
}

func (q *Queries) UpdateRoutingRule(ctx context.Context, arg UpdateRoutingRuleParams) (RoutingRule, error) {
	row := q.db.QueryRow(ctx, updateRoutingRule,
		arg.Name,
		arg.Position,
		arg.IsActive,
		arg.Conditions,
		arg.TeamID,
		arg.Skills,
		arg.OrganizationID,
		arg.ID,
	)
	var i RoutingRule
	err := row.Scan(
		&i.ID,
		&i.Uuid,
		&i.OrganizationID,
		&i.Name,
		&i.Position,
		&i.IsActive,
		&i.Conditions,
		&i.TeamID,
		&i.Skills,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const upsertRoutingCursor = `-- name: UpsertRoutingCursor :exec
INSERT INTO routing_cursors (organization_id, scope_key, last_user_id, updated_at)
VALUES ($1, $2, $3, NOW())
ON CONFLICT (organization_id, scope_key) DO UPDATE SET last_user_id = EXCLUDED.last_user_id, updated_at = NOW()
`

type UpsertRoutingCursorParams struct {
	OrganizationID int64  `json:"organization_id"`
	ScopeKey       string `json:"scope_key"`
	LastUserID     int64  `json:"last_user_id"`
}

func (q *Queries) UpsertRoutingCursor(ctx context.Context, arg UpsertRoutingCursorParams) error {
	_, err := q.db.Exec(ctx, upsertRoutingCursor, arg.OrganizationID, arg.ScopeKey, arg.LastUserID)
	return err
}

const upsertRoutingSettings = `-- name: UpsertRoutingSettings :one
INSERT INTO routing_settings (organization_id, enabled, strategy, respect_capacity, vip_account_owner, reassign_on_offline, unanswered_minutes, updated_at)
VALUES ($1, $2, $3, $4, $5,
        $6, $7, NOW())
ON CONFLICT (organization_id) DO UPDATE SET
    enabled = EXCLUDED.enabled, strategy = EXCLUDED.strategy, respect_capacity = EXCLUDED.respect_capacity,
    vip_account_owner = EXCLUDED.vip_account_owner, reassign_on_offline = EXCLUDED.reassign_on_offline,
    unanswered_minutes = EXCLUDED.unanswered_minutes, updated_at = NOW()
RETURNING organization_id, enabled, strategy, respect_capacity, vip_account_owner, reassign_on_offline, unanswered_minutes, updated_at
`

type UpsertRoutingSettingsParams struct {
	OrganizationID    int64       `json:"organization_id"`
	Enabled           bool        `json:"enabled"`
	Strategy          string      `json:"strategy"`
	RespectCapacity   bool        `json:"respect_capacity"`
	VipAccountOwner   bool        `json:"vip_account_owner"`
	ReassignOnOffline bool        `json:"reassign_on_offline"`
	UnansweredMinutes pgtype.Int4 `json:"unanswered_minutes"`
}

func (q *Queries) UpsertRoutingSettings(ctx context.Context, arg UpsertRoutingSettingsParams) (RoutingSetting, error) {
	row := q.db.QueryRow(ctx, upsertRoutingSettings,
		arg.OrganizationID,
		arg.Enabled,
		arg.Strategy,
		arg.RespectCapacity,
		arg.VipAccountOwner,
		arg.ReassignOnOffline,
		arg.UnansweredMinutes,
	)
	var i RoutingSetting
	err := row.Scan(
		&i.OrganizationID,
		&i.Enabled,
		&i.Strategy,
		&i.RespectCapacity,
		&i.VipAccountOwner,
		&i.ReassignOnOffline,
		&i.UnansweredMinutes,
		&i.UpdatedAt,
	)
	return i, err
}
